    doc.setTextColor(15, 23, 42);
    doc.text("CDSS QUAN LY VANCOMYCIN - PHIEU HO TRO QUYET DINH LAM SANG", pageWidth / 2, y4, { align: "center" });
    y4 += 5;
    doc.setFont("helvetica", "normal");
    doc.setFontSize(8.5);
    doc.setTextColor(100, 116, 139);
    doc.text("Can cu: Huong dan ASHP/IDSA/SIDP 2020 & Bang hieu chinh lieu khang sinh BVDK Ca Mau", pageWidth / 2, y4, { align: "center" });
    y4 += 3;
